import inspect

from functools import wraps
from robot.running import EXECUTION_CONTEXTS
from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper

from taf.rfrl.csv4all.resources.utilities.utilities import set_robot_test_variable, test_logger


def decorate_cls_methods(decorator, *decorator_args):
    def decorate_class(cls):
        for method_name, method in inspect.getmembers(cls):
            if (inspect.ismethod(method) or inspect.isfunction(method)) and not (
                    inspect.isbuiltin(method) or inspect.ismodule(method)):
                if method_name.startswith("_"):
                    continue
                setattr(cls, method_name, decorator(method, *decorator_args))
        return cls

    return decorate_class


class KeywordRobot(RobotWrapper):
    def __exit__(self, exc_type, exc_val, exc_tb):
        sorted_levels = sorted(list(self.levels), reverse=False)
        try:
            self.levels[sorted_levels[-1]].__exit__(exc_type, exc_val, exc_tb)
        except Exception:
            pass


def function_wrapper(function):
    @wraps(function)
    def logged_function(*args, **kwargs):
        arguments = " | ".join([f"{arg}" for arg in args] +
                               [f"{kwarg}={value}" for kwarg, value in kwargs.items()])
        function_formatted_name = " ".join([word.title() for word in function.__name__.split("_")])
        if EXECUTION_CONTEXTS.current:
            with KeywordRobot(f"{function_formatted_name}", "kw") as w:
                test_logger(f"Arguments: [{arguments}]", console=False)
                result = function(*args, **kwargs)
                test_logger(f"Return: {result}", console=False)
            return result
        return function(*args, **kwargs)

    return logged_function


def method_decorator(class_identifier=None):
    def method_wrapper(method):

        @wraps(method)
        def logged_method(self, *args, **kwargs):
            method_formatted_name = " ".join([word.title() for word in method.__name__.split("_")]).lstrip()
            if class_identifier:
                method_name = f"{getattr(self, class_identifier)}.{method_formatted_name}"
            else:
                node = [arg for arg in args if hasattr(arg, 'node_alias')]
                if node:
                    method_name = f"{node[0].node_alias}.{method_formatted_name}"
                else:
                    method_name = f"{method.__qualname__.split('.')[0]}.{method_formatted_name}"
            arguments = " | ".join([f"{arg}" for arg in args] +
                                   [f"{kwarg}={value}" for kwarg, value in kwargs.items()])
            if EXECUTION_CONTEXTS.current:
                with KeywordRobot(f"{method_name}", "kw") as w:
                    test_logger(f"Arguments: [{arguments}]", console=False)
                    result = method(self, *args, **kwargs)
                    test_logger(f"Return: {result}", console=False)
                return result
            return method(self, *args, **kwargs)

        return logged_method

    return method_wrapper


def verify_state_decorator(class_identifier=None):
    def method_wrapper(method):

        @wraps(method)
        def logged_method(self, *args, **kwargs):
            method_formatted_name = " ".join([word.title() for word in method.__name__.split("_")]).lstrip()
            if class_identifier:
                method_name = f"{getattr(self, class_identifier)}.{method_formatted_name}"
            else:
                node = [arg for arg in args if hasattr(arg, 'node_alias')]
                if node:
                    method_name = f"{node[0].node_alias}.{method_formatted_name}"
                else:
                    method_name = f"{method.__qualname__.split('.')[0]}.{method_formatted_name}"
            method_arguments = list(inspect.signature(method).parameters)
            method_arguments.remove('self')
            distname = [args[method_arguments.index(arg)] for arg in method_arguments
                        if arg == 'cell_id' or arg == 'module_id']
            object_id = distname[0].split('/')[-1] if distname[0] else ""
            arguments = " | ".join([f"{arg}" for arg in args] +
                                   [f"{kwarg}={value}" for kwarg, value in kwargs.items()])
            if EXECUTION_CONTEXTS.current:
                with KeywordRobot(f"{method_name}: {object_id}", "kw") as w:
                    test_logger(f"Arguments: [{arguments}]", console=False)
                    result = method(self, *args, **kwargs)
                    test_logger(f"Return: {result}", console=False)
                return result
            return method(self, *args, **kwargs)

        return logged_method

    return method_wrapper


def admin_method_decorator(method):
    @wraps(method)
    def admin_decorated_method(self, *args, **kwargs):
        test_logger(f"Execution of {method.__name__} on BTS {self.node_id}", console=False)
        if "connection" in inspect.signature(method).parameters.keys():
            if "connection" not in kwargs.keys() and self.admin_connection not in args:
                kwargs["connection"] = self.admin_connection
        return method(self, *args, **kwargs)

    return admin_decorated_method


def _project_robot_var_type(function_name, arg_name, value):
    temp_arg_name = f"{function_name}_{arg_name}"
    set_robot_test_variable(temp_arg_name, value)
    return temp_arg_name


def test_setup_wrapper(test_setup):
    @wraps(test_setup)
    def setup(self, *args, **kwargs):
        if EXECUTION_CONTEXTS.current:
            with RobotWrapper(wrap_name="CSV4All Test Case Setup", wrap_type="kw"):
                test_setup(self, *args, **kwargs)
        else:
            test_setup(self, *args, **kwargs)

    return setup


def test_teardown_wrapper(test_teardown):
    @wraps(test_teardown)
    def teardown(self, *args, **kwargs):
        if EXECUTION_CONTEXTS.current:
            with RobotWrapper(wrap_name="CSV4All Test Case teardown", wrap_type="teardown"):
                test_teardown(self, *args, **kwargs)
        else:
            test_teardown(self, *args, **kwargs)

    return teardown


def wrapper_decorator(method):
    @wraps(method)
    def wrapper(self, *args, **kwargs):
        if EXECUTION_CONTEXTS.current:
            node = [arg for arg in args if getattr(arg, 'node_alias', None)][0]
            with RobotWrapper(wrap_name=f"{node.node_alias}", wrap_type="kw") as robot_wrapper:
                method(self, *args, **kwargs)
                robot_wrapper.close_level_to(max(robot_wrapper.levels.keys()))
        else:
            method(self, *args, **kwargs)

    return wrapper
